from fastapi import FastAPI
import asyncio

def s_start():
    print("SYNC START", flush=True)

def s_stop():
    print("SYNC STOP", flush=True)

app = FastAPI(on_startup=[s_start], on_shutdown=[s_stop])

@app.get("/health")
async def health():
    return {"ok": True}

async def test_startup_shutdown():
    from fastapi.testclient import TestClient
    with TestClient(app) as client:
        client.get("/health")

if __name__ == "__main__":
    asyncio.run(test_startup_shutdown())
